INSERT INTO _migration_586_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wisc_health_b003_003', 'topic_wassce_intsci_health', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'The most effective way to control the breeding of mosquitoes in a community is to', 'multiple_choice', NULL, '["A. plant more flowers around houses","B. burn firewood every evening","C. drain or cover all stagnant water around homes","D. keep water containers uncovered"]', 'C', 'Mosquitoes lay their eggs in stagnant water, so draining puddles and covering water-storage containers removes their breeding sites. Flowers do not affect breeding, smoke from firewood gives only temporary relief, and uncovered containers create even more breeding sites. Therefore the correct answer is C: drain or cover all stagnant water around homes.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_health_b003_004', 'topic_wassce_intsci_health', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Chlorine is added to public water supplies mainly because it', 'multiple_choice', NULL, '["A. removes suspended solids from the water","B. softens the hard water","C. improves the colour of the water","D. kills disease-causing micro-organisms in the water"]', 'D', 'Chlorination disinfects water: chlorine destroys bacteria and viruses, making the treated water safe to drink. Suspended solids are removed earlier by coagulation, sedimentation and filtration, and chlorine neither softens hard water nor changes its colour. Therefore the correct answer is D: kills disease-causing micro-organisms in the water.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, NULL),
('q_wisc_health_b003_005', 'topic_wassce_intsci_health', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Depletion of the ozone layer is caused mainly by the release of', 'multiple_choice', NULL, '["A. chlorofluorocarbons from old refrigerants and aerosols","B. carbon dioxide from burning fossil fuels","C. sulphur dioxide from factories","D. smoke from bushfires"]', 'A', 'Chlorofluorocarbons (CFCs) rise into the stratosphere, where ultraviolet radiation breaks them down and the chlorine released destroys ozone molecules. Carbon dioxide drives global warming rather than ozone depletion, and sulphur dioxide causes acid rain — common confusions. Therefore the correct answer is A: chlorofluorocarbons from old refrigerants and aerosols.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, NULL),
('q_wisc_health_b003_006', 'topic_wassce_intsci_health', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A water treatment plant adds 0.5 g of chlorine for every 100 litres of water. Calculate the mass of chlorine needed to treat 4,000 litres of water.', 'calculation', NULL, NULL, '20 g', 'Each 100 litres needs 0.5 g, and 4,000 litres contains 4,000 ÷ 100 = 40 units of 100 litres. Mass of chlorine = 40 × 0.5 g = 20 g. Answer: 20 g of chlorine is needed.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL),
('q_wisc_health_b003_007', 'topic_wassce_intsci_health', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Water for a rural community comes from a shallow well.', 'structured', NULL, NULL, '(a) Any two of: runoff carrying refuse or faeces into the well; animals drinking directly from the well; buckets and ropes handled with dirty hands; pit latrines sited too close to the well. (b) Any two of: boiling the water to kill germs; adding chlorine (for example WaterGuard) at the correct dose; filtering and then disinfecting; solar disinfection in clear bottles exposed to sunlight. (c) To kill or remove germs that cause water-borne diseases such as cholera, typhoid and dysentery.', '(a) Any two of: runoff carrying refuse or faeces into the well; animals drinking directly from the well; buckets and ropes handled with dirty hands; pit latrines sited too close to the well. (b) Any two of: boiling the water to kill germs; adding chlorine (for example WaterGuard) at the correct dose; filtering and then disinfecting; solar disinfection in clear bottles exposed to sunlight. (c) To kill or remove germs that cause water-borne diseases such as cholera, typhoid and dysentery.', 'medium', '5', '5', NULL, NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, NULL),
('q_wisc_cells_b003_001', 'topic_wassce_intsci_cells', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which part of a living cell regulates the passage of substances across its boundary?', 'multiple_choice', NULL, '["A. Cell wall","B. Cell membrane","C. Nucleus","D. Cytoplasm"]', 'B', 'The cell membrane is partially permeable, allowing some substances to pass while blocking others. The cell wall is fully permeable and only gives support, the nucleus controls the activities of the cell, and the cytoplasm is the site of chemical reactions. Therefore the correct answer is B: Cell membrane.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL);
INSERT INTO _migration_586_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_wisc_health_b003_007_a', 'q_wisc_health_b003_007', 'a', 'State two ways in which the well water may become contaminated.', '2', 'Any two of: runoff carrying refuse or faeces into the well; animals drinking directly from the well; buckets and ropes handled with dirty hands; pit latrines sited too close to the well.', '1'),
('sqp_q_wisc_health_b003_007_b', 'q_wisc_health_b003_007', 'b', 'Describe two methods of purifying the water for drinking.', '2', 'Any two of: boiling the water to kill germs; adding chlorine (for example WaterGuard) at the correct dose; filtering and then disinfecting; solar disinfection in clear bottles exposed to sunlight.', '2'),
('sqp_q_wisc_health_b003_007_c', 'q_wisc_health_b003_007', 'c', 'State one reason why water must be purified before drinking.', '1', 'To kill or remove germs that cause water-borne diseases such as cholera, typhoid and dysentery.', '3');
INSERT INTO _migration_586_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_586_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_586_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'wassce-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_586_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_586_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_586_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'wassce-int-science-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM _migration_586_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_586_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_586_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_586_expected e ON e.id = r.question_id WHERE r.batch_id IS 'wassce-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_586_expected e ON e.id = q.id) = 6 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_586_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
